@Test
public void testPadRight() {
    assertEquals("sample", StringUtils.rightPad("sample", 0, '0'));
    assertEquals("sample", StringUtils.rightPad("sample", -5, '0'));
    assertEquals("sample0000", StringUtils.rightPad("sample", 10, '0'));
    assertEquals("0000000000", StringUtils.rightPad("", 10, '0'));
    // multiple pads
    assertEquals("samplexyxy", StringUtils.rightPad("sample", 10, "xy"));
    // less than 1 pad
    assertEquals("samplexy", StringUtils.rightPad("sample", 8, "xyz"));
    // exactly 1 pad
    assertEquals("samplexy", StringUtils.rightPad("sample", 8, "xy"));
    // null pad
    assertEquals("sample    ", StringUtils.rightPad("sample", 10, null));
    assertNull(StringUtils.rightPad(null, 0, '0'));
}

@Test
public void testPadLeft() {
    assertEquals("sample", StringUtils.leftPad("sample", 0, '0'));
    assertEquals("0000sample", StringUtils.leftPad("sample", 10, '0'));
    assertEquals("0000000000", StringUtils.leftPad("", 10, '0'));
    // multiple pads
    assertEquals("xyxysample", StringUtils.leftPad("sample", 10, "xy"));
    // less than 1 pad
    assertEquals("xysample", StringUtils.leftPad("sample", 8, "xyz"));
    // exactly 1 pad
    assertEquals("xysample", StringUtils.leftPad("sample", 8, "xy"));
    // null pad
    assertEquals("    sample", StringUtils.leftPad("sample", 10, null));
    assertNull(StringUtils.leftPad(null, 0, '0'));
}

