        bytes -= previousBytes;
        previousBytes = bytes;
        final long millis = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
        final long eventsPerSecond = (updateCountPerThread * numThreads * 1000) / millis;
        final String eps = NumberFormat.getInstance().format(eventsPerSecond);
        final long bytesPerSecond = bytes * 1000 / millis;
        final String bps = NumberFormat.getInstance().format(bytesPerSecond);
        if (j == 0) {
            logger.info("{} ms to insert {} updates using {} threads, *as a warmup!* {} events per second, {} bytes per second", millis, updateCountPerThread * numThreads, numThreads, eps, bps);
        } else {
            logger.info("{} ms to insert {} updates using {} threads, {} events per second, {} bytes per second", millis, updateCountPerThread * numThreads, numThreads, eps, bps);
        }
    }
}

