    final ControllerService service = new JsonTreeReader();
    runner.addControllerService("record-reader", service);
    runner.enableControllerService(service);
    runner.setProperty(ConsumeKinesisStream.RECORD_READER, "record-reader");
    runner.removeProperty(ConsumeKinesisStream.RECORD_WRITER);
    runner.assertNotValid();
    final AssertionError assertionError = assertThrows(AssertionError.class, runner::assertValid);
    assertEquals(assertionError.getMessage(), String.format("Processor has 1 validation failures:\n" + "'%s' is invalid because %s must be set if %s is set in order to write FlowFiles as Records.\n", ConsumeKinesisStream.RECORD_WRITER.getName(), ConsumeKinesisStream.RECORD_WRITER.getDisplayName(), ConsumeKinesisStream.RECORD_READER.getDisplayName()));
}

