    when(tlsConfiguration.getEnabledProtocols()).thenReturn(new String[] { latestProtocol });
    when(tlsConfiguration.isKeystorePopulated()).thenReturn(true);
    when(tlsConfiguration.getKeystorePath()).thenReturn(KEY_STORE_PATH);
