    // backward compatible.
    runner.clearTransferState();
    attributes.put(CoreAttributes.MIME_TYPE.key(), CompressionStrategy.BZIP2.getMimeTypes()[0]);
    runner.enqueue(getSamplePath("SampleFile1.txt.bz2"), attributes);
    runner.run();
