    runner.setProperty(service, ElasticSearchClientService.HTTP_HOSTS, "blah://invalid");
    final List<ConfigVerificationResult> results = service.verify(new MockConfigurationContext(service, getClientServiceProperties(), runner.getProcessContext().getControllerServiceLookup(), null), runner.getLogger(), Collections.emptyMap());
    assertEquals(4, results.size());
    assertEquals(3, results.stream().filter(result -> result.getOutcome() == ConfigVerificationResult.Outcome.SKIPPED).count(), results.toString());
    assertEquals(1, results.stream().filter(result -> Objects.equals(result.getVerificationStepName(), ElasticSearchClientServiceImpl.VERIFICATION_STEP_CLIENT_SETUP) && result.getExplanation().contains(ElasticSearchClientService.HTTP_HOSTS.getDisplayName()) && result.getOutcome() == ConfigVerificationResult.Outcome.FAILED).count(), results.toString());
}

