@Test
public void testObjectsBound() {
    final JavaObjectBindings bindings = new JavaObjectBindings();
    final String objectId = "oTestObject1";
    final String methodName = "testMethod";
    final CommandBuilder builder = new CommandBuilder(bindings, objectId, methodName);
    final Iterable<Object> iterable = new Iterable<>() {

        @Override
        public Iterator<Object> iterator() {
            return null;
        }
    };
    final Object[] args = new Object[] { "string", 1, 1.0F, 1.0D, 1L, null, true, 'c', (byte) 1, (short) 1, "hello world".getBytes(), new Object(), new int[2], new Object[2], new ArrayList<>(), new HashSet<>(), iterable };
    final String command = builder.buildCommand(args);
    // Ensure that we bind an ID for each object (except for String and byte[]) and not the primitives.
    // So we should have a bound ID for each of the following:
    // new Object()
    // new int[2]
    // new Object[2]
    // new ArrayList<>()
    // new HashSet<>()
    // iterable
    assertEquals(6, builder.getBoundIds().size());
    // Ensure that the command has the appropriate header
    final String[] commandSplits = command.split("\n");
    assertEquals(CommandBuilder.METHOD_INVOCATION_START_CLAUSE.trim(), commandSplits[0]);
    assertEquals(objectId, commandSplits[1]);
    assertEquals(methodName, commandSplits[2]);
    // Verify the primitive arguments
    assertTrue(commandSplits[3].contains("string"));
    assertTrue(commandSplits[4].contains("1"));
    assertTrue(commandSplits[5].contains("1.0"));
    assertTrue(commandSplits[6].contains("1.0"));
    assertTrue(commandSplits[7].contains("1"));
    // n is used for null values
    assertEquals("n", commandSplits[8]);
    assertTrue(commandSplits[9].contains("true"));
    assertTrue(commandSplits[10].contains("c"));
    assertTrue(commandSplits[11].contains("1"));
    assertTrue(commandSplits[12].contains("1"));
    final List<String> boundIds = builder.getBoundIds();
    // Verify the object arguments
    for (int splitIndex = 14; splitIndex < commandSplits.length - 1; splitIndex++) {
        final String argId = commandSplits[splitIndex].substring(1);
        assertTrue(boundIds.contains(argId));
        assertSame(args[splitIndex - 3], bindings.getBoundObject(argId));
    }
    // Ensure that the command ends with the appropriate footer
    assertEquals(CommandBuilder.METHOD_INVOCATION_END_CLAUSE.trim(), commandSplits[commandSplits.length - 1]);
}

@Test
public void testObjectBoundUnboundWithSingleInvocation() {
    final Object[] args = new Object[] { new Object() };
    final InvocationBindings invocationBindings = gateway.beginInvocation("o123", NOP_METHOD, args);
    final String objectId = gateway.putNewObject(args[0]);
    final List<String> objectIds = invocationBindings.getObjectIds();
    assertEquals(List.of(objectId), objectIds);
    assertEquals(args[0], gateway.getObject(objectId));
    gateway.endInvocation(invocationBindings);
    gateway.deleteObject(objectId);
    assertNull(gateway.getObject(objectId));
}

@Test
public void testObjectBoundNotUnboundWhileInvocationActive() {
    final Object[] args = new Object[] { new Object() };
    final InvocationBindings invocationBindings = gateway.beginInvocation("o123", NOP_METHOD, args);
    final String objectId = gateway.putNewObject(args[0]);
    final List<String> objectIds = invocationBindings.getObjectIds();
    assertEquals(List.of(objectId), objectIds);
    assertEquals(args[0], gateway.getObject(objectId));
    gateway.deleteObject(objectId);
    // gateway.deleteObject should not remove the value because the invocation is still active
    assertEquals(args[0], gateway.getObject(objectId));
    // After calling endInvocation, the object should be cleaned up.
    gateway.endInvocation(invocationBindings);
    assertNull(gateway.getObject(objectId));
}

@Test
public void testEndInvocationDifferentThread() throws InterruptedException {
    final Object[] args = new Object[] { new Object() };
    final InvocationBindings invocationBindings = gateway.beginInvocation("o123", NOP_METHOD, args);
    final String objectId = gateway.putNewObject(args[0]);
    final List<String> objectIds = invocationBindings.getObjectIds();
    assertEquals(List.of(objectId), objectIds);
    assertEquals(args[0], gateway.getObject(objectId));
    gateway.deleteObject(objectId);
    // gateway.deleteObject should not remove the value because the invocation is still active
    assertEquals(args[0], gateway.getObject(objectId));
    Thread.ofVirtual().start(() -> {
        gateway.endInvocation(invocationBindings);
    }).join();
    assertNull(gateway.getObject(objectId));
}

@Test
public void testMultipleInvocationsActive() {
    final Object[] args = new Object[] { new Object() };
    // Simulate 5 different threads making invocations into the Python process
    final List<InvocationBindings> bindings = new ArrayList<>();
    for (int i = 0; i < 5; i++) {
        final InvocationBindings invocationBindings = gateway.beginInvocation("o123", NOP_METHOD, args);
        bindings.add(invocationBindings);
    }
    // Create an object while there are 5 invocations active. We don't know which invocation caused
    // the object to be created, so we can't unbind it until all invocations are complete.
    final String objectId = gateway.putNewObject(args[0]);
    // Simulate Python process garbage collecting the object after 2 of the invocations are complete
    gateway.endInvocation(bindings.removeFirst());
    gateway.endInvocation(bindings.removeFirst());
    gateway.deleteObject(objectId);
    // We should now be able to add additional invocations, and they should not prevent the already-bound
    // object from being cleaned up.
    for (int i = 0; i < 3; i++) {
        gateway.beginInvocation("o123", NOP_METHOD, args);
    }
    // As each of the invocations complete, we should find the object is still bound
    for (final InvocationBindings invocationBindings : bindings) {
        assertNotNull(gateway.getObject(objectId));
        gateway.endInvocation(invocationBindings);
    }
    // When the final invocation completes, the object should be unbound
    assertNull(gateway.getObject(objectId));
}

