        final Optional<SNMPSingleResponse> optionalResponse = getSNMPHandler.get(getFlowFileAttributesForSnmpGet(INVALID_OID, READ_ONLY_OID_2), target);
        if (optionalResponse.isPresent()) {
            final SNMPSingleResponse response = optionalResponse.get();
            final List<SNMPValue> actualVariableBindings = response.getVariableBindings();
            final List<SNMPValue> expectedVariableBindings;
            final List<Function<SNMPValue, Object>> equalsProperties = Arrays.asList(SNMPValue::getOid, SNMPValue::getVariable);
            if (version == SnmpConstants.version1) {
                expectedVariableBindings = Arrays.asList(new SNMPValue(INVALID_OID, "Null"), new SNMPValue(READ_ONLY_OID_2, READ_ONLY_OID_VALUE_2));
                assertEquals(NO_SUCH_NAME, response.getErrorStatusText());
            } else {
                expectedVariableBindings = Arrays.asList(new SNMPValue(INVALID_OID, NO_SUCH_OBJECT), new SNMPValue(READ_ONLY_OID_2, READ_ONLY_OID_VALUE_2));
                assertEquals(SUCCESS, response.getErrorStatusText());
            }
            assertEquals(new HashSet<>(EqualsWrapper.wrapList(actualVariableBindings, equalsProperties)), new HashSet<>(EqualsWrapper.wrapList(expectedVariableBindings, equalsProperties)));
        } else {
            fail("Response is not present.");
        }
    } catch (Exception e) {
        fail(e);
    } finally {
        agent.stop();
        agent.unregister();
    }
}

