@Test
void validateUpdateFlowFileAttributes() {
    final PDU pdu = new PDU();
    pdu.setErrorIndex(0);
    pdu.setErrorStatus(0);
    pdu.setType(4);
    final Map<String, String> attributeMap = SNMPUtils.getPduAttributeMap(pdu);
    assertEquals("0", attributeMap.get(SNMPUtils.SNMP_PROP_PREFIX + "errorIndex"));
    assertEquals("0", attributeMap.get(SNMPUtils.SNMP_PROP_PREFIX + "errorStatus"));
    assertEquals("4", attributeMap.get(SNMPUtils.SNMP_PROP_PREFIX + "type"));
}

@Test
void testGetConnectionPropertiesPrivateKeyService() {
    final Map<PropertyDescriptor, String> properties = new HashMap<>();
    properties.put(SnowflakeComputingConnectionPool.PRIVATE_KEY_SERVICE, PRIVATE_KEY_SERVICE_ID);
    final MockProcessContext controllerServiceLookup = new MockProcessContext(new NoOpProcessor());
    when(privateKeyService.getIdentifier()).thenReturn(PRIVATE_KEY_SERVICE_ID);
    controllerServiceLookup.addControllerService(privateKeyService, Map.of(), null);
    final Map<String, String> environmentVariables = Map.of();
    final MockConfigurationContext context = new MockConfigurationContext(properties, controllerServiceLookup, environmentVariables);
    when(privateKeyService.getPrivateKey()).thenReturn(privateKey);
    final Map<String, String> connectionProperties = pool.getConnectionProperties(context);
    assertNotNull(connectionProperties);
    assertFalse(connectionProperties.isEmpty());
    final String authenticator = connectionProperties.get(SFSessionProperty.AUTHENTICATOR.getPropertyKey());
    assertEquals(SNOWFLAKE_JWT, authenticator);
    final String privateKeyBase64 = connectionProperties.get(SFSessionProperty.PRIVATE_KEY_BASE64.getPropertyKey());
    assertNotNull(privateKeyBase64);
    assertTrue(privateKeyBase64.startsWith(PEM_HEADER_BASE64), "PEM Header encoded with Bas64 not found");
    assertEquals(pemPrivateKeyBase64, privateKeyBase64);
}

@Test
@Timeout(60)
public void testReceiveSingleTweetInStream() {
    String sampleTweet = "{\"data\":{\"id\":\"123\",\"text\":\"This is a sample tweet and is not real!\"}}";
    MockResponse response = new MockResponse.Builder().code(200).body(sampleTweet).addHeader("Content-Type", "application/json").build();
    mockWebServer.enqueue(response);
    runner.setProperty(ConsumeTwitter.ENDPOINT, ConsumeTwitter.ENDPOINT_SAMPLE);
    runner.setProperty(ConsumeTwitter.QUEUE_SIZE, "10000");
    runner.setProperty(ConsumeTwitter.BATCH_SIZE, "10");
    runner.setProperty(ConsumeTwitter.BACKFILL_MINUTES, "0");
    runner.assertValid();
    // The TwitterStreamAPI class spins up another thread and might not be done queueing tweets in one run of the
    // processor, so the test will timeout after 60 seconds.
    runner.run(1, false, true);
    while (runner.getFlowFilesForRelationship(ConsumeTwitter.REL_SUCCESS).isEmpty()) {
        runner.run(1, false, false);
    }
    runner.stop();
    // there should only be a single FlowFile containing a tweet
    runner.assertTransferCount(ConsumeTwitter.REL_SUCCESS, 1);
    MockFlowFile flowFile = runner.getFlowFilesForRelationship(ConsumeTwitter.REL_SUCCESS).getFirst();
    String expectedTweet = "[{\"data\":{\"id\":\"123\",\"text\":\"This is a sample tweet and is not real!\"}}]";
    flowFile.assertContentEquals(expectedTweet);
    flowFile.assertAttributeEquals(CoreAttributes.MIME_TYPE.key(), "application/json");
    flowFile.assertAttributeEquals("tweets", "1");
}

