    runner.setProperty(ControlRate.MAX_DATA_RATE, "1 MB");
    // MAX_DATA_RATE is ignored
    runner.assertValid();
    runner.removeProperty(ControlRate.MAX_RATE);
    // MAX_RATE is a required property for this rate control criteria
    runner.assertNotValid();
    runner.clearProperties();
    runner.setProperty(ControlRate.RATE_CONTROL_CRITERIA, ControlRate.RateControlCriteria.FLOWFILE_RATE);
    // MAX_RATE is not set
    runner.assertNotValid();
    runner.setProperty(ControlRate.MAX_RATE, "1 MB");
    // MAX_RATE is not an integer
    runner.assertNotValid();
    runner.setProperty(ControlRate.MAX_RATE, "1");
    runner.assertValid();
    runner.setProperty(ControlRate.MAX_COUNT_RATE, "1");
    // MAX_COUNT_RATE is ignored
    runner.assertValid();
    runner.removeProperty(ControlRate.MAX_RATE);
    // MAX_RATE is a required property for this rate control criteria
    runner.assertNotValid();
    runner.clearProperties();
    runner.setProperty(ControlRate.RATE_CONTROL_CRITERIA, ControlRate.RateControlCriteria.ATTRIBUTE_RATE);
    runner.setProperty(ControlRate.RATE_CONTROL_ATTRIBUTE_NAME, "count");
    // MAX_RATE is not set
    runner.assertNotValid();
    runner.setProperty(ControlRate.MAX_RATE, "1 MB");
    // MAX_RATE is not an integer
    runner.assertNotValid();
    runner.setProperty(ControlRate.MAX_RATE, "1");
    runner.assertValid();
    runner.setProperty(ControlRate.MAX_COUNT_RATE, "1");
    // MAX_COUNT_RATE is ignored
    runner.assertValid();
    runner.removeProperty(ControlRate.MAX_RATE);
    // MAX_RATE is a required property for this rate control criteria
    runner.assertNotValid();
    runner.setProperty(ControlRate.MAX_RATE, "1");
    runner.removeProperty(ControlRate.RATE_CONTROL_ATTRIBUTE_NAME);
    // RATE_CONTROL_ATTRIBUTE_NAME is a required property for this rate control criteria
    runner.assertNotValid();
    runner.clearProperties();
    runner.setProperty(ControlRate.RATE_CONTROL_CRITERIA, ControlRate.RateControlCriteria.DATA_OR_FLOWFILE_RATE);
    runner.setProperty(ControlRate.MAX_DATA_RATE, "1 MB");
    runner.setProperty(ControlRate.MAX_COUNT_RATE, "1");
    runner.setProperty(ControlRate.MAX_COUNT_RATE, "2");
    // both MAX_DATA_RATE and MAX_COUNT_RATE are set
    runner.assertValid();
    runner.removeProperty(ControlRate.MAX_COUNT_RATE);
    // MAX_COUNT_RATE is not set
    runner.assertNotValid();
    runner.setProperty(ControlRate.MAX_COUNT_RATE, "1");
    runner.removeProperty(ControlRate.MAX_DATA_RATE);
    // MAX_DATA_RATE is not set
    runner.assertNotValid();
    runner.setProperty(ControlRate.MAX_DATA_RATE, "1 MB");
    runner.setProperty(ControlRate.MAX_RATE, "1 MB");
    // MAX_RATE is ignored
    runner.assertValid();
}

