@Test
void testFlatten() throws JsonProcessingException {
    final String json = "{
" + "    "test": {
" + "        "msg": "Hello, world"
" + "    },
" + "    "first": {
" + "        "second": {
" + "            "third": [
" + "                "one",
" + "                "two",
" + "                "three",
" + "                "four",
" + "                "five"
" + "            ]
" + "        }
" + "    }
" + "}";
    final Map parsed = (Map) baseTest(testRunner, json, 2);
    assertEquals(parsed.get("test.msg"), "Hello, world", "test.msg should exist, but doesn't");
    assertEquals(parsed.get("first.second.third"), Arrays.asList("one", "two", "three", "four", "five"), "Three level block doesn't exist.");
}

