    List<MockFlowFile> splits = runner.getFlowFilesForRelationship(SplitText.REL_SPLITS);
    String fragmentUUID = splits.get(0).getAttribute(SplitText.FRAGMENT_ID);
    for (int i = 0; i < splits.size(); i++) {
