        split.assertAttributeEquals(SplitText.SPLIT_LINE_COUNT, "5");
        split.assertAttributeEquals(SplitText.FRAGMENT_SIZE, "70");
        split.assertAttributeEquals(SplitText.FRAGMENT_INDEX, String.valueOf(i + 1));
