    runner.setProperty(SplitText.HEADER_LINE_COUNT, "0");
    runner.setProperty(SplitText.LINE_SPLIT_COUNT, "0");
    runner.setProperty(SplitText.FRAGMENT_MAX_SIZE, "71 B");
