    final ByteArrayOutputStream baos = new ByteArrayOutputStream();
    final String output;
    try (final WriteFastCSVResult writer = new WriteFastCSVResult(csvFormat, schema, new SchemaNameAsAttribute(), baos, RecordFieldType.DATE.getDefaultFormat(), RecordFieldType.TIME.getDefaultFormat(), RecordFieldType.TIMESTAMP.getDefaultFormat(), true, "ASCII")) {
        writer.beginRecordSet();
        writer.write(record);
        writer.finishRecordSet();
        writer.flush();
        output = baos.toString();
    }
    // The first field is quoted as the Quote Mode defaults to MINIMAL and it has an escaped character in it
    assertEquals("id,name\n\"1\"\"\",John Doe\n", output);
}

