    assertEquals(RecordFieldType.DATE.getDataType(timeValueInference.getDateFormat()), schema.getDataType("DOB").get());
    assertEquals(RecordFieldType.CHOICE.getChoiceDataType(RecordFieldType.TIME.getDataType("HH:mm:ss"), RecordFieldType.STRING.getDataType()), schema.getDataType("TOB").get());
