@Test
public void testWebSocketConnect() throws Exception {
    final String identifier = JettyWebSocketServer.class.getSimpleName();
    final JettyWebSocketServer server = new JettyWebSocketServer();
    runner.addControllerService(identifier, server);
    runner.setProperty(server, JettyWebSocketServer.PORT, "0");
    runner.enableControllerService(server);
    server.registerProcessor(ROOT_ENDPOINT_ID, runner.getProcessor());
    final String command = String.class.getName();
    final AtomicBoolean connected = new AtomicBoolean();
    final WebSocketClient client = new WebSocketClient();
    final Session.Listener.AutoDemanding adapter = new TrackedAutoDemandingListener(connected);
    try {
        client.start();
        final URI uri = getWebSocketUri(server.getListeningPort());
        final Future<Session> connectSession = client.connect(adapter, uri);
        final Session session = connectSession.get(TIMEOUT_SECONDS, TimeUnit.SECONDS);
        session.sendText(command, new Callback.Completable());
        session.close();
        assertTrue(connected.get(), "Connection not found");
    } finally {
        client.stop();
        runner.disableControllerService(server);
    }
}

@Test
public void testMapExtractor() {
    // GIVEN
    final Map<String, String> attributes = new HashMap<>();
    attributes.put("header.AUTHORIZATION", "AUTH_VALUE");
    attributes.put("header.MULTI_HEADER_KEY", "FIRST, SECOND   ,THIRD");
    attributes.put("header.dots.dots.dots.DOTS_KEY", "DOTS_VALUE");
    attributes.put("something.else.SOMETHING_ELSE_KEY", "SOMETHING_ELSE_VALUE");
    attributes.put("header.EMPTY_VALUE_KEY", "");
    attributes.put("headerButNotReally.UNRECOGNIZED", "NOT_A_HEADER_VALUE");
    final Map<String, List<String>> expected = new HashMap<>();
    expected.put("AUTHORIZATION", Collections.singletonList("AUTH_VALUE"));
    expected.put("MULTI_HEADER_KEY", Arrays.asList("FIRST", "SECOND", "THIRD"));
    expected.put("dots.dots.dots.DOTS_KEY", Collections.singletonList("DOTS_VALUE"));
    // WHEN
    final Map<String, List<String>> actual = HeaderMapExtractor.getHeaderMap(attributes);
    // THEN
    assertEquals(expected, actual);
    assertEquals(expected.size(), actual.size());
    for (Map.Entry<String, List<String>> entry : actual.entrySet()) {
        assertTrue(expected.containsKey(entry.getKey()));
        final List<String> actualHeaderValues = entry.getValue();
        final List<String> expectedHeaderValues = expected.get(entry.getKey());
        for (int i = 0; i < actualHeaderValues.size(); i++) {
            assertEquals(expectedHeaderValues.get(i), actualHeaderValues.get(i));
        }
    }
}

@Test
@Timeout(value = 10)
public void testProcessesBlockedEvents() {
    testRunner.setProperty(ConsumeWindowsEventLog.MAX_EVENT_QUEUE_SIZE, "1");
    testRunner.run(1, false, true);
    EventSubscribeXmlRenderingCallback renderingCallback = getRenderingCallback();
    List<String> eventXmls = Arrays.asList("one", "two", "three", "four", "five", "six");
    List<WinNT.HANDLE> eventHandles = mockEventHandles(wEvtApi, kernel32, eventXmls);
    AtomicBoolean done = new AtomicBoolean(false);
    new Thread(() -> {
        for (WinNT.HANDLE eventHandle : eventHandles) {
            renderingCallback.onEvent(WEvtApi.EvtSubscribeNotifyAction.DELIVER, null, eventHandle);
        }
        done.set(true);
    }).start();
    // Wait until the thread has really started
    while (testRunner.getFlowFilesForRelationship(ConsumeWindowsEventLog.REL_SUCCESS).isEmpty()) {
        testRunner.run(1, false, false);
    }
    // Process rest of events
    while (!done.get()) {
        testRunner.run(1, false, false);
    }
    testRunner.run(1, true, false);
    List<MockFlowFile> flowFilesForRelationship = testRunner.getFlowFilesForRelationship(ConsumeWindowsEventLog.REL_SUCCESS);
    assertEquals(eventXmls.size(), flowFilesForRelationship.size());
    for (int i = 0; i < eventXmls.size(); i++) {
        flowFilesForRelationship.get(i).assertContentEquals(eventXmls.get(i));
    }
}

