@Test
public void testGetTargetUriAndUris() {
    final RemoteProcessGroupDTO dto = new RemoteProcessGroupDTO();
    assertNull(dto.getTargetUri());
    dto.setTargetUris("http://node1:8080/nifi, http://node2:8080/nifi");
    assertEquals("http://node1:8080/nifi", dto.getTargetUri(), "If targetUris are set but targetUri is not, it should returns the first uri of the targetUris");
    assertEquals("http://node1:8080/nifi, http://node2:8080/nifi", dto.getTargetUris());
    dto.setTargetUri("http://node3:9090/nifi");
    assertEquals("http://node3:9090/nifi", dto.getTargetUri(), "If both targetUri and targetUris are set, each returns its own values");
    assertEquals("http://node1:8080/nifi, http://node2:8080/nifi", dto.getTargetUris());
    dto.setTargetUris(null);
    assertEquals("http://node3:9090/nifi", dto.getTargetUri());
    assertEquals("http://node3:9090/nifi", dto.getTargetUris(), "getTargetUris should return targetUri when it's not set");
}

