    queue.setFlowFilePartitioner(new StaticFlowFilePartitioner(0));
    QueuePartition firstPartition = queue.putAndGetPartition(new MockFlowFileRecord());
    final NodeIdentifier node1Identifier = nodeIds.get(0);
