    }
    assertEquals("", baos.toString());
    assertEquals(0, baos.size());
    baos.reset();
    try (final InputStream in = repository.read(claim3)) {
        StreamUtils.copy(in, baos);
    }
    assertEquals(" World", baos.toString());
}

