@Timeout(10)
@Test
public void testGetClaimantCountWhileMarkingDestructable() throws InterruptedException, ExecutionException {
    final StandardResourceClaimManager manager = new StandardResourceClaimManager();
    for (int i = 0; i < 50000; i++) {
        final ResourceClaim rc = manager.newResourceClaim("container", "section", String.valueOf(i), false, false);
        manager.markDestructable(rc);
    }
    final Object completedObject = new Object();
    final CompletableFuture<Object> future = new CompletableFuture<>();
    final ResourceClaim lastClaim = manager.newResourceClaim("container", "section", "lastOne", false, false);
    final Thread backgroundThread = new Thread(() -> {
        manager.markDestructable(lastClaim);
        future.complete(completedObject);
    });
    backgroundThread.start();
    Thread.sleep(10);
    assertEquals(0, manager.getClaimantCount(lastClaim));
    assertNull(future.getNow(null));
    manager.drainDestructableClaims(new ArrayList<>(), 1);
    assertSame(completedObject, future.get());
}

@Test
public void testUpdatedAttributesMaintainedWhenFlowFileRemoved() {
    final StandardRepositoryRecord record = new StandardRepositoryRecord((FlowFileQueue) null);
    final Map<String, String> updatedAttributes = new HashMap<>();
    updatedAttributes.put("abc", "xyz");
    updatedAttributes.put("hello", "123");
    final String uuid = UUID.randomUUID().toString();
    final FlowFileRecord flowFileRecord = new StandardFlowFileRecord.Builder().addAttribute("uuid", uuid).addAttributes(updatedAttributes).build();
    record.setWorking(flowFileRecord, updatedAttributes, false);
    final Map<String, String> updatedWithId = new HashMap<>(updatedAttributes);
    updatedWithId.put("uuid", uuid);
    assertEquals(updatedWithId, record.getUpdatedAttributes());
    assertFalse(record.isContentModified());
    record.setWorking(flowFileRecord, true);
    assertTrue(record.isContentModified());
    record.setWorking(flowFileRecord, false);
    // Should still be true because it was modified previously
    assertTrue(record.isContentModified());
    record.markForDelete();
    assertEquals(updatedWithId, record.getUpdatedAttributes());
}

