        assertEquals(0, mgr.getWriterCount());
        final EventIndexSearcher eventSearcher = mgr.borrowIndexSearcher(dir);
        assertEquals(0, mgr.getWriterCount());
        assertEquals(1, mgr.getSearcherCount());
        boolean removed = mgr.removeIndex(dir);
        assertFalse(removed);
