        assertEquals(0, mgr.getSearcherCount());
        FileUtils.deleteFile(dir, true);
        assertFalse(dir.exists());
        assertThrows(FileNotFoundException.class, () -> mgr.borrowIndexSearcher(dir));
    } finally {
        if (dir.exists()) {
            FileUtils.deleteFile(dir, true);
        }
    }
}

