public void testDatabaseRestorationAfterCorruptedFiles() throws DatabaseException, IOException {
    final DatabaseManager testSubject1 = getTestSubject();
    final Client client1 = testSubject1.acquireClient();
    for (int i = 1; i <= 10; i++) {
