    bucket.setRevision(initialRevision);
    Bucket createdBucket = client.target(createURL("buckets")).request().post(Entity.entity(bucket, MediaType.APPLICATION_JSON), Bucket.class);
    // When: that bucket deleted
    final Bucket deletedBucket = client.target(createURL("buckets/" + createdBucket.getIdentifier())).queryParam("version", createdBucket.getRevision().getVersion().longValue()).request().delete(Bucket.class);
    // Then: the body of the server response matches the bucket that was deleted
    //  and: the bucket is no longer accessible (resource not found)
    // authorizedActions will not be present in deletedBucket
    createdBucket.setPermissions(null);
    // links will not be present in deletedBucket
    createdBucket.setLink(null);
    assertBucketsEqual(createdBucket, deletedBucket, true);
    final Response response = client.target(createURL("buckets/" + createdBucket.getIdentifier())).request().get();
    assertEquals(404, response.getStatus());
}

