    final VersionedFlowSnapshot createdFlowSnapshot = client.target(createURL("buckets/{bucketId}/flows/{flowId}/versions")).resolveTemplate("bucketId", bucketId).resolveTemplate("flowId", flowId).request().post(Entity.entity(flowSnapshot, MediaType.APPLICATION_JSON), VersionedFlowSnapshot.class);
    assertNotNull(createdFlowSnapshot.getFlow());
    final VersionedFlowSnapshot importedFlowSnapshot = client.target(createURL("buckets/{bucketId}/flows/{flowId}/versions/import")).resolveTemplate("bucketId", bucketId).resolveTemplate("flowId", flowId).request().post(Entity.entity(createdFlowSnapshot, MediaType.APPLICATION_JSON), VersionedFlowSnapshot.class);
