    final VersionedFlowSnapshotMetadata[] versionedFlowSnapshots = client.target(createURL("buckets/{bucketId}/flows/{flowId}/versions")).resolveTemplate("bucketId", bucketId).resolveTemplate("flowId", flowId).request().get(VersionedFlowSnapshotMetadata[].class);
