    assertFlowSnapshotsEqual(importedFlowSnapshot, importedFlowSnapshotByLink, true);
    // =========== Import another version ===========
    final File testSnapshotFile = new File("src/test/resources/test-versioned-flow-snapshot.json");
    // Imported Flow id = 2
