    WebTarget clientRequestTarget = client.target(createURL("buckets/{bucketId}/flows/{flowId}/versions/import")).resolveTemplate("bucketId", importedBucketId).resolveTemplate("flowId", importedFlowId);
    final VersionedFlowSnapshot nextImportedFlowSnapshot = clientRequestTarget.request(MediaType.APPLICATION_JSON).header("content-type", MediaType.APPLICATION_JSON).header("comments", "This is a test version").post(Entity.entity(testSnapshotFile, MediaType.APPLICATION_JSON), VersionedFlowSnapshot.class);
    assertNotNull(nextImportedFlowSnapshot);
    assertBucketsEqual(importedFlowSnapshot.getBucket(), nextImportedFlowSnapshot.getBucket(), true);
    assertEquals(importedFlowId, nextImportedFlowSnapshot.getSnapshotMetadata().getFlowIdentifier());
    assertEquals(3, nextImportedFlowSnapshot.getSnapshotMetadata().getVersion());
}

