    final String contentsAfterRestore = getClientUtil().getFlowFileContentAsUtf8(writeVersionToTerminate.getId(), 0);
    assertEquals(EXPECTED_FLOW_FILE_CONTENT, contentsAfterRestore);
}

@Test
public void testUploadStandardNars() throws NiFiClientException, IOException, InterruptedException {
    final NarUploadUtil narUploadUtil = new NarUploadUtil(getNifiClient());
    narUploadUtil.verifyNarSummaries(0);
    final File narsLocation = new File(NAR_PROVIDER_NARS_LOCATION);
    if (!narsLocation.exists()) {
        throw new IllegalStateException("NARs location does not exist at: " + narsLocation.getAbsolutePath());
    }
    // Upload processor NAR and wait until is reaches Missing Dependency
    final NarSummaryDTO uploadedProcessorsNar = narUploadUtil.uploadNar(narsLocation, PROCESSORS_NAR_ID);
    waitFor(narUploadUtil.getWaitForNarStateSupplier(uploadedProcessorsNar.getIdentifier(), NarState.MISSING_DEPENDENCY));
    // Upload controller service NAR and wait until is reaches Missing Dependency
    final NarSummaryDTO uploadedControllerServiceNar = narUploadUtil.uploadNar(narsLocation, CONTROLLER_SERVICE_NAR_ID);
    waitFor(narUploadUtil.getWaitForNarStateSupplier(uploadedControllerServiceNar.getIdentifier(), NarState.MISSING_DEPENDENCY));
    // Upload controller service API NAR and wait until is reaches Installed, will cause previous two NARs to also install
    final NarSummaryDTO uploadedControllerServiceApiNar = narUploadUtil.uploadNar(narsLocation, CONTROLLER_SERVICE_API_NAR_ID);
    waitFor(narUploadUtil.getWaitForNarStateSupplier(uploadedControllerServiceApiNar.getIdentifier(), NarState.INSTALLED));
    // Verify all NARs are now installed
    final NarSummariesEntity narSummaries = narUploadUtil.verifyNarSummaries(3);
    for (final NarSummaryEntity narSummaryEntity : narSummaries.getNarSummaries()) {
        assertEquals(NarState.INSTALLED.getValue(), narSummaryEntity.getNarSummary().getState());
    }
    // Verify processors from the uploaded NAR are loaded and available to use
    final ProcessorTypesEntity allProcessorTypes = getNifiClient().getFlowClient().getProcessorTypes();
    assertNotNull(allProcessorTypes);
    assertNotNull(allProcessorTypes.getProcessorTypes());
    final Set<DocumentedTypeDTO> processorsFromUploadedNar = allProcessorTypes.getProcessorTypes().stream().filter(processorType -> matchingBundles(processorType.getBundle(), uploadedProcessorsNar.getCoordinate())).collect(Collectors.toSet());
    assertNotNull(processorsFromUploadedNar);
    assertFalse(processorsFromUploadedNar.isEmpty());
    // Verify controller services from the uploaded NAR are loaded and available to use
    final ControllerServiceTypesEntity allControllerServiceTypes = getNifiClient().getFlowClient().getControllerServiceTypes();
    assertNotNull(allControllerServiceTypes);
    assertNotNull(allControllerServiceTypes.getControllerServiceTypes());
    final Set<DocumentedTypeDTO> controllerServicesFromUploadedNar = allControllerServiceTypes.getControllerServiceTypes().stream().filter(serviceType -> matchingBundles(serviceType.getBundle(), uploadedControllerServiceNar.getCoordinate())).collect(Collectors.toSet());
    assertNotNull(controllerServicesFromUploadedNar);
    assertFalse(controllerServicesFromUploadedNar.isEmpty());
    // Verify retrieving the processor NAR details
    final NarDetailsEntity processorNarDetails = getNifiClient().getControllerClient().getNarDetails(uploadedProcessorsNar.getIdentifier());
    assertNotNull(processorNarDetails);
    assertNotNull(processorNarDetails.getNarSummary());
    assertNotNull(processorNarDetails.getProcessorTypes());
    assertEquals(1, processorNarDetails.getProcessorTypes().size());
    assertNotNull(processorNarDetails.getDependentCoordinates());
    assertEquals(0, processorNarDetails.getDependentCoordinates().size());
    // Verify retrieving the service API NAR details
    final NarDetailsEntity serviceApiNarDetails = getNifiClient().getControllerClient().getNarDetails(uploadedControllerServiceApiNar.getIdentifier());
    assertNotNull(serviceApiNarDetails);
    assertNotNull(serviceApiNarDetails.getNarSummary());
    assertNotNull(serviceApiNarDetails.getProcessorTypes());
    assertEquals(0, serviceApiNarDetails.getProcessorTypes().size());
    assertNotNull(serviceApiNarDetails.getDependentCoordinates());
    assertEquals(2, serviceApiNarDetails.getDependentCoordinates().size());
    // Create instance of the custom processor
    final NarCoordinateDTO uploadedProcessorCoordinate = uploadedProcessorsNar.getCoordinate();
    final ProcessorEntity customProcessor = getClientUtil().createProcessor(PROCESSOR_CLASS_NAME, uploadedProcessorCoordinate.getGroup(), uploadedProcessorCoordinate.getArtifact(), uploadedProcessorCoordinate.getVersion());
    assertNotNull(customProcessor.getComponent());
    assertNotNull(customProcessor.getComponent().getExtensionMissing());
    assertFalse(customProcessor.getComponent().getExtensionMissing());
    // Verify service API NAR can be replaced while other NARs depend on it
    final NarSummaryDTO replacedServiceApiNar = narUploadUtil.uploadNar(narsLocation, CONTROLLER_SERVICE_API_NAR_ID);
    waitFor(narUploadUtil.getWaitForNarStateSupplier(replacedServiceApiNar.getIdentifier(), NarState.INSTALLED));
    // Verify processors NAR can be replaced
    final NarSummaryDTO replacedProcessorsNar = narUploadUtil.uploadNar(narsLocation, PROCESSORS_NAR_ID);
    waitFor(narUploadUtil.getWaitForNarStateSupplier(replacedProcessorsNar.getIdentifier(), NarState.INSTALLED));
    // Verify controller services NAR can be replaced
    final NarSummaryDTO replacedControllerServiceNar = narUploadUtil.uploadNar(narsLocation, CONTROLLER_SERVICE_NAR_ID);
    waitFor(narUploadUtil.getWaitForNarStateSupplier(replacedControllerServiceNar.getIdentifier(), NarState.INSTALLED));
    // Verify service API NAR can't be deleted while other NARs depend on it
    assertThrows(NiFiClientException.class, () -> getNifiClient().getControllerClient().deleteNar(uploadedControllerServiceApiNar.getIdentifier(), true));
    // Delete other NARs first
    narUploadUtil.deleteNar(uploadedProcessorsNar);
    narUploadUtil.deleteNar(uploadedControllerServiceNar);
    narUploadUtil.deleteNar(uploadedControllerServiceApiNar);
    // Verify no NARs exist
    narUploadUtil.verifyNarSummaries(0);
    // Verify custom processor is ghosted
    final String customProcessorId = customProcessor.getId();
    waitFor(() -> {
        final ProcessorEntity customProcessorAfterDelete = getNifiClient().getProcessorClient().getProcessor(customProcessorId);
        logger.info("Waiting for processor {} to be considered missing", customProcessorId);
        return customProcessorAfterDelete.getComponent().getExtensionMissing();
    });
    // Restore NARs
    narUploadUtil.uploadNar(narsLocation, CONTROLLER_SERVICE_API_NAR_ID);
    narUploadUtil.uploadNar(narsLocation, CONTROLLER_SERVICE_NAR_ID);
    final NarSummaryDTO restoredProcessorsNar = narUploadUtil.uploadNar(narsLocation, PROCESSORS_NAR_ID);
    waitFor(narUploadUtil.getWaitForNarStateSupplier(restoredProcessorsNar.getIdentifier(), NarState.INSTALLED));
    // Verify processor is un-ghosted
    waitFor(() -> {
        final ProcessorEntity customProcessorAfterDelete = getNifiClient().getProcessorClient().getProcessor(customProcessorId);
        logger.info("Waiting for processor {} to be considered not missing", customProcessorId);
        return !customProcessorAfterDelete.getComponent().getExtensionMissing();
    });
}

@Test
public void testSynchronizeAssets() throws NiFiClientException, IOException, InterruptedException {
    waitForAllNodesConnected();
    final Map<String, String> paramValues = Map.of("name", "foo", "fileToIngest", "");
    final ParameterContextEntity paramContext = getClientUtil().createParameterContext("testSynchronizeAssets", paramValues);
    // Set the Parameter Context on the root Process Group
    setParameterContext("root", paramContext);
    // Create a Processor and update it to reference Parameter "name"
    final ProcessorEntity ingest = getClientUtil().createProcessor("IngestFile");
    getClientUtil().updateProcessorProperties(ingest, Map.of("Filename", "#{fileToIngest}", "Delete File", "false"));
    getClientUtil().updateProcessorSchedulingPeriod(ingest, "10 mins");
    // Create an asset and update the parameter to reference the asset
    final File assetFile = new File("src/test/resources/sample-assets/helloworld.txt");
    final AssetEntity asset = createAsset(paramContext.getId(), assetFile);
    final ParameterContextUpdateRequestEntity referenceAssetUpdateRequest = getClientUtil().updateParameterAssetReferences(paramContext, Map.of("fileToIngest", List.of(asset.getAsset().getId())));
    getClientUtil().waitForParameterContextRequestToComplete(paramContext.getId(), referenceAssetUpdateRequest.getRequest().getRequestId());
    final ProcessorEntity terminate = getClientUtil().createProcessor("TerminateFlowFile");
    final ConnectionEntity connection = getClientUtil().createConnection(ingest, terminate, "success");
    waitForValidProcessor(ingest.getId());
    getClientUtil().startProcessor(ingest);
    waitForQueueCount(connection.getId(), getNumberOfNodes());
    final String contents = getClientUtil().getFlowFileContentAsUtf8(connection.getId(), 0);
    assertEquals("Hello, World!", contents);
    // Check that the file exists in the assets directory.
    final File node1Dir = getNiFiInstance().getNodeInstance(1).getInstanceDirectory();
    final File node1AssetsDir = new File(node1Dir, "assets");
    final File node1ContextDir = new File(node1AssetsDir, paramContext.getId());
    assertTrue(node1ContextDir.exists());
    final File node2Dir = getNiFiInstance().getNodeInstance(2).getInstanceDirectory();
    final File node2AssetsDir = new File(node2Dir, "assets");
    final File node2ContextDir = new File(node2AssetsDir, paramContext.getId());
    assertTrue(node2ContextDir.exists());
    // List assets and verify the expected asset is returned
    final AssetsEntity assetListing = assertAssetListing(paramContext.getId(), 1);
    assertAssetExists(asset, assetListing);
    // Stop node2
    disconnectNode(2);
    getNiFiInstance().getNodeInstance(2).stop();
    // Delete node2's assets
    FileUtils.deleteFilesInDir(node2AssetsDir, (dir, name) -> true, null, true, true);
    assertTrue(node2AssetsDir.delete());
    assertFalse(node2AssetsDir.exists());
    // Start node2 again
    getNiFiInstance().getNodeInstance(2).start(true);
    reconnectNode(2);
    waitForAllNodesConnected();
    // Verify node2 asset directories are back
    assertTrue(node2AssetsDir.exists());
    assertTrue(node2ContextDir.exists());
    final File[] node2AssetFiles = node2ContextDir.listFiles();
    assertNotNull(node2AssetFiles);
    assertEquals(1, node2AssetFiles.length);
    // Ensure ingest processor is valid
    waitForValidProcessor(ingest.getId());
    getClientUtil().stopProcessor(ingest);
    getClientUtil().waitForStoppedProcessor(ingest.getId());
}

@Test
public void testSynchronizeAssetsAfterChangingReferences() throws NiFiClientException, IOException, InterruptedException {
    waitForAllNodesConnected();
    final Map<String, String> paramValues = Map.of("name", "foo", "filesToIngest", "");
    final ParameterContextEntity paramContext = getClientUtil().createParameterContext("testSynchronizeAssetsAfterChangingReferences", paramValues);
    // Set the Parameter Context on the root Process Group
    setParameterContext("root", paramContext);
    // Create a Processor and update it to reference Parameter "name"
    final ProcessorEntity generateFlowFile = getClientUtil().createProcessor("GenerateFlowFile");
    getClientUtil().updateProcessorProperties(generateFlowFile, Map.of("Text", "#{filesToIngest}"));
    getClientUtil().updateProcessorSchedulingPeriod(generateFlowFile, "10 mins");
    // Create two assets and update the parameter to reference the assets
    final AssetEntity asset1 = createAsset(paramContext.getId(), new File("src/test/resources/sample-assets/helloworld.txt"));
    final AssetEntity asset2 = createAsset(paramContext.getId(), new File("src/test/resources/sample-assets/helloworld2.txt"));
    final List<String> assetIds = List.of(asset1.getAsset().getId(), asset2.getAsset().getId());
    final ParameterContextUpdateRequestEntity referenceAssetUpdateRequest = getClientUtil().updateParameterAssetReferences(paramContext, Map.of("filesToIngest", assetIds));
    getClientUtil().waitForParameterContextRequestToComplete(paramContext.getId(), referenceAssetUpdateRequest.getRequest().getRequestId());
    // Connect the Generate processor to a Terminate processor and generate flow files
    final ProcessorEntity terminate = getClientUtil().createProcessor("TerminateFlowFile");
    final ConnectionEntity connection = getClientUtil().createConnection(generateFlowFile, terminate, "success");
    waitForValidProcessor(generateFlowFile.getId());
    getClientUtil().startProcessor(generateFlowFile);
    waitForQueueCount(connection.getId(), getNumberOfNodes());
    // Verify flow files reference both assets
    final String flowFileContents = getClientUtil().getFlowFileContentAsUtf8(connection.getId(), 0);
    assertTrue(flowFileContents.contains(asset1.getAsset().getName()));
    assertTrue(flowFileContents.contains(asset2.getAsset().getName()));
    // Verify the contents of the assets directory for each node
    final File node1Dir = getNiFiInstance().getNodeInstance(1).getInstanceDirectory();
    final File node1AssetsDir = new File(node1Dir, "assets");
    final File node1ContextDir = new File(node1AssetsDir, paramContext.getId());
    assertTrue(node1ContextDir.exists());
    final File node2Dir = getNiFiInstance().getNodeInstance(2).getInstanceDirectory();
    final File node2AssetsDir = new File(node2Dir, "assets");
    final File node2ContextDir = new File(node2AssetsDir, paramContext.getId());
    assertTrue(node2ContextDir.exists());
    // List assets and verify the expected asset is returned
    final AssetsEntity assetListing = assertAssetListing(paramContext.getId(), 2);
    assertAssetExists(asset1, assetListing);
    // Stop node2
    disconnectNode(2);
    getNiFiInstance().getNodeInstance(2).stop();
    // Delete node2's assets
    FileUtils.deleteFilesInDir(node2AssetsDir, (dir, name) -> true, null, true, true);
    assertTrue(node2AssetsDir.delete());
    assertFalse(node2AssetsDir.exists());
    // Modify the parameter context on node1 to only reference asset1
    final ParameterContextEntity retrievedContext = getNifiClient().getParamContextClient().getParamContext(paramContext.getId(), false);
    final ParameterContextUpdateRequestEntity changeAssetsUpdateRequest = getClientUtil().updateParameterAssetReferences(retrievedContext, Map.of("filesToIngest", List.of(asset1.getAsset().getId())));
    getClientUtil().waitForParameterContextRequestToComplete(paramContext.getId(), changeAssetsUpdateRequest.getRequest().getRequestId());
    // Start node2 again
    getNiFiInstance().getNodeInstance(2).start(true);
    reconnectNode(2);
    waitForAllNodesConnected();
    // Verify node2 asset directories are back
    assertTrue(node2AssetsDir.exists());
    assertTrue(node2ContextDir.exists());
    // Stop generate processor and clear queue
    getClientUtil().stopProcessor(generateFlowFile);
    getClientUtil().waitForStoppedProcessor(generateFlowFile.getId());
    getClientUtil().startProcessor(terminate);
    waitForQueueCount(connection.getId(), 0);
    getClientUtil().stopProcessor(terminate);
    getClientUtil().waitForStoppedProcessor(terminate.getId());
    // Start generate again
    getClientUtil().startProcessor(generateFlowFile);
    waitForQueueCount(connection.getId(), getNumberOfNodes());
    // Verify flow files only reference the first asset
    final String flowFile1Contents = getClientUtil().getFlowFileContentAsUtf8(connection.getId(), 0);
    assertTrue(flowFile1Contents.contains(asset1.getAsset().getName()));
    assertFalse(flowFile1Contents.contains(asset2.getAsset().getName()));
    final String flowFile2Contents = getClientUtil().getFlowFileContentAsUtf8(connection.getId(), 1);
    assertTrue(flowFile2Contents.contains(asset1.getAsset().getName()));
    assertFalse(flowFile2Contents.contains(asset2.getAsset().getName()));
    getClientUtil().stopProcessor(generateFlowFile);
    getClientUtil().waitForStoppedProcessor(generateFlowFile.getId());
}

