            return false;
        }
        final FlowFileEntity flowFile = getClientUtil().getQueueFlowFile(generateToSplit.getId(), 0);
        if (!Boolean.TRUE.equals(flowFile.getFlowFile().getPenalized())) {
            return false;
        }
        return getConnectionQueueSize(splitToTerminate.getId()) == 0;
