    final long replaceTextCount = v2Contents.getProcessors().stream().map(ProcessorEntity::getComponent).filter(proc -> proc.getName().equals("ReplaceText")).filter(proc -> proc.getId().equals(replaceTextProcessors.get(0).getId())).count();
    assertEquals(1, replaceTextCount);
