public void testDynamicTableWriter() {
    table.addRow("1", "Bucket 1", "12345-12345-12345-12345-12345-12345", "");
    table.addRow("2", "Bucket 2 - This is a really really really long name", "12345-12345-12345-12345-12345-12345", "This is a really really really really really really really really really really long description");
    table.addRow("3", "Bucket 3", "12345-12345-12345-12345-12345-12345", null);
    tableWriter.write(table, printStream);
    final String result = new String(outputStream.toByteArray(), StandardCharsets.UTF_8);
    final String expected = "\n" + "#   Name                                   Id                                    Description                                \n" + "-   ------------------------------------   -----------------------------------   ----------------------------------------   \n" + "1   Bucket 1                               12345-12345-12345-12345-12345-12345                                              \n" + "2   Bucket 2 - This is a really reall...   12345-12345-12345-12345-12345-12345   This is a really really really really...   \n" + "3   Bucket 3                               12345-12345-12345-12345-12345-12345   (empty)                                    \n" + "\n";
    assertEquals(expected, result);
}

@Test
public void testWhenAllDescriptionsAreEmpty() {
    table.addRow("1", "Bucket 1", "12345-12345-12345-12345-12345-12345", null);
    table.addRow("2", "Bucket 2", "12345-12345-12345-12345-12345-12345", null);
    tableWriter.write(table, printStream);
    final String result = new String(outputStream.toByteArray(), StandardCharsets.UTF_8);
    final String expected = "\n" + "#   Name       Id                                    Description   \n" + "-   --------   -----------------------------------   -----------   \n" + "1   Bucket 1   12345-12345-12345-12345-12345-12345   (empty)       \n" + "2   Bucket 2   12345-12345-12345-12345-12345-12345   (empty)       \n" + "\n";
    assertEquals(expected, result);
}

